{"file_path":"src/graph.js","content":"/** Ordering the task graph. */

/** One dependency cycle, carrying the names from the re-entered task around and back to it. */
export class CycleError extends Error {
  /**
   * @param {string[]} names - the cycle's names, starting and ending with the re-entered task.
   */
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.name = 'CycleError'
    this.names = names
  }
}

/**
 * Find the first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle's names, from the re-entered task back to it, or null.
 */
function findCycle(tasks) {
  const state = new Map() // name -> 'visiting' | 'done'
  const stack = []
  function visit(name) {
    state.set(name, 'visiting')
    stack.push(name)
    for (const need of [...tasks.get(name).needs].sort()) {
      const status = state.get(need)
      if (status === 'visiting') {
        const start = stack.indexOf(need)
        return [...stack.slice(start), need]
      } else if (status !== 'done') {
        const found = visit(need)
        if (found) return found
      }
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }
  for (const name of [...tasks.keys()].sort()) {
    if (state.get(name) === 'done') continue
    const found = visit(name)
